attribute vec3 aO, aD; attribute vec4 aW; attribute float aT, aP; uniform float uTime; varying vec3 vN, vV; varying float vHeat;
    void main(){
      float u = uTime - aT; if (u < 0.){ gl_Position = vec4(2.,2.,2.,1.); return; }
      float y = aW.x, a = aW.y, sd = aW.z, fr = aW.w, a0 = a - sd*6.2832*fr;
      float rev = smoothstep(fr*0.15, fr*0.15 + .04, u);           // winds on around the target
      float kp = uTime - aP, pulled = step(.5, aP)*step(0., kp);
      float pc = clamp((kp - 0.12)/0.22, 0., 1.), pe = pc*pc*pc*pulled;
      float gone = pulled > .5 ? clamp((kp - 0.34)/.25, 0., 1.)              // pulled: goes only after the target has arrived
                               : clamp((u - 1.60)/0.32, 0., 1.);    // no recast: goes with the chain
      float sc = rev*(1. - smoothstep(fr*.6, fr*.6 + .4, gone));                                // unwinds from the chain's end
      if (sc < .01){ gl_Position = vec4(2.,2.,2.,1.); return; }
      vec3 C = aO + aD*pe + vec3(0., y, 0.);
      float tilt = .07*sd*sin(a - a0);                                                          // slightly helical, not a flat ring
      vec3 Rd = vec3(cos(a), 0., sin(a));
      vec3 T = normalize(vec3(-sin(a), .07*sd*cos(a - a0)/0.30, cos(a)));
      vec3 up = vec3(0., 1., 0.);
      bool odd = mod(fr*11.0 + .5, 2.) > 1.;
      vec3 ax = odd ? Rd : up, az = odd ? up : Rd;
      vec3 wp = (T*position.x*.12 + ax*position.y*.07 + az*position.z*.07)*sc;
      vN = normalize(T*normal.x/.12 + ax*normal.y/.07 + az*normal.z/.07);
      vec3 P = C + Rd*0.30 + vec3(0., tilt, 0.) + wp;
      float heat = .3 + .9*exp(-u*6.) + 2.*exp(-pow(kp/.06, 2.))*pulled + .8*pe + .9*gone*(1. - gone)*4.;
      vV = normalize(cameraPosition - P); vHeat = heat;
      gl_Position = projectionMatrix*viewMatrix*vec4(P, 1.);
    }

layers.fragment:
uniform vec3 uGold, uOrange, uMoon; varying vec3 vN, vV; varying float vHeat;
    void main(){
      vec3 n = normalize(vN), v = normalize(vV);
      float rim = pow(1. - abs(dot(n, v)), 2.4);                                // glow lives on the contour: reads as light, not metal
      vec3 col = mix(uOrange, uGold, .45 + .45*rim);
      vec3 c = col*(.025 + .36*rim)*(.45 + vHeat) + vec3(1., .95, .86)*rim*max(vHeat - .7, 0.)*.2;
      gl_FragColor = vec4(c, 1.);
    }

